/**
 * @file li_expansion_test.cpp
 * @brief `li` loads the exact 64-bit value, and its expansion keeps the
 *        instruction count it always had (known_issues 110).
 *
 * The 32-bit step of the expansion was `lui hi; addi lo`. For every value
 * in 0x7FFFF800..0x7FFFFFFF, hi rounds up to 0x80000, lui sign-extends it,
 * and the result was 0xFFFFFFFF_7FFFFxxx on every model.
 *
 * Values and counts are generated by ~/atlas-verify/e3/gen_li.py: the
 * +-2^11 / 2^31 / 2^32 / 2^63 boundaries, 0x7FFFF800..0x7FFFFFFF in steps of
 * 128 plus its last two values, their negatives, and 32 seeded random
 * 64-bit values. The expected count is what the assembler emitted BEFORE
 * the fix. The whole range, and 2000 random values, are audited out of
 * tree by ~/atlas-verify/e3/li_audit.py, which also decodes and emulates
 * every expansion in Python.
 *
 * Models: rvss, h_f, h_nf and nh_f. `li` cannot be padded from the source
 * (the assembler emits the chain), and nh_nf cannot run a dependent pair
 * back to back by design (known_issues 77); the Python emulation is its
 * check, since it shares the encoding with the other four.
 */
#include "isa_case_support.h"

#include <gtest/gtest.h>

